for group,expr in rules.items():
 for id in groups[group]:
  r=rs[id];q=r['q'];n=nums(q['q']);values=eval(expr,{'__builtins__':{},'sum':sum},{'n':n})
  out.append({'id':id,'group':group,'visibleStem':q['q'],'visibleInputs':n,'equation':expr,'computedValues':values,'key':q['options'][r['answer']],'feedback':q['feedback'],'review':'Independent arithmetic; direction, classification and rounding checked with the full answer set.'})
(P/'independent_checkpoint_calculations.json').write_text(json.dumps(out,indent=2),encoding='utf8')
print('Independent checkpoint calculations',len(out),'families',len(rules))
